import numpy as np

def natural_spline_M(t, y):
    t = np.asarray(t, dtype=float); y = np.asarray(y, dtype=float)
    h = np.diff(t)
    n = len(t)
    A = np.zeros((n - 2, n - 2)); b = np.zeros(n - 2)
    for i in range(1, n - 1):
        j = i - 1
        if j > 0:
            A[j, j - 1] = h[i - 1]
        A[j, j] = 2 * (h[i - 1] + h[i])
        if j < n - 3:
            A[j, j + 1] = h[i]
        b[j] = 6 * ((y[i + 1] - y[i]) / h[i] - (y[i] - y[i - 1]) / h[i - 1])
    M = np.zeros(n)
    M[1:-1] = np.linalg.solve(A, b)
    return M

def spline_eval(t, y, M, x):
    t = np.asarray(t, dtype=float); y = np.asarray(y, dtype=float)
    k = min(max(int(np.searchsorted(t, x)) - 1, 0), len(t) - 2)
    a, b = t[k], t[k + 1]
    h = b - a
    return float(M[k] * (b - x) ** 3 / (6 * h) + M[k + 1] * (x - a) ** 3 / (6 * h)
                 + (y[k] / h - M[k] * h / 6) * (b - x) + (y[k + 1] / h - M[k + 1] * h / 6) * (x - a))

def zero_price(t, y, T):
    return 100 * np.exp(-T * spline_eval(t, y, natural_spline_M(t, y), T))
